#!/bin/bash
IFS='.' read -r i1 i2 i3 i4 <<< "$1"; for i in 0 8 16 24; do s=$(( $2 - i )); (( s >= 8 )) && v=255 || (( s <= 0 )) && v=0 || v=$(( 255 ^ ((1 << (8 - s)) - 1) )); eval m$((i/8+1))=$v; done; n1=$((i1 & m1)); n2=$((i2 & m2)); n3=$((i3 & m3)); n4=$((i4 & m4)); b1=$((n1 | (255 - m1))); b2=$((n2 | (255 - m2))); b3=$((n3 | (255 - m3))); b4=$((n4 | (255 - m4))); printf "%d.%d.%d.%d - %d.%d.%d.%d" "$n1" "$n2" "$n3" "$((n4 + 1))" "$b1" "$b2" "$b3" "$((b4 - 1))"
